// ValidateInlinePromptSize rejects prompts that are too large to safely pass as
// a single CLI argument on providers that do not support stdin prompt input.
func ValidateInlinePromptSize(displayName, prompt string) error {
	if len(prompt) <= MaxInlinePromptBytes {
		return nil
	}
	return fmt.Errorf(
		"%s prompt too large for CLI argument transport (%d bytes > %d bytes); choose a summary provider that accepts stdin for large transcripts",
		displayName,
		len(prompt),
		MaxInlinePromptBytes,
	)
}

func StripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}

// ClaudeGenerator generates summaries using the Claude CLI.
type ClaudeGenerator struct {
	// TextGenerator is the primitive used to obtain raw model output.
	// If nil, uses the built-in Claude Code text generator.
	TextGenerator agent.TextGenerator

	// Model is the Claude model to use for summarization.
	// If empty, defaults to DefaultModel ("sonnet").
	Model string
}

// Generate creates a summary from checkpoint data by calling the Claude CLI.
func (g *ClaudeGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	// Format the transcript for the prompt
	transcriptText := FormatCondensedTranscript(input)

	// Build the prompt
	prompt := buildSummarizationPrompt(transcriptText)

	model := g.Model
	if model == "" {
		model = DefaultModel
	}

	textGenerator := g.TextGenerator
	if textGenerator == nil {
		var err error
		textGenerator, err = defaultTextGeneratorFactory()
		if err != nil {
			return nil, err
		}
	}

	resultJSON, err := textGenerator.GenerateText(ctx, prompt, model)
	if err != nil {
		return nil, fmt.Errorf("failed to generate summary text: %w", err)
	}

	return parseSummaryText(resultJSON)
}

// buildSummarizationPrompt creates the prompt for the Claude CLI.
func buildSummarizationPrompt(transcriptText string) string {
	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)

package summarize

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// TextGeneratorAdapter uses an agent.TextGenerator with Entire's shared
// summary prompt and response parser.
type TextGeneratorAdapter struct {
	TextGenerator agent.TextGenerator
	Model         string
}

// Generate creates a summary using the shared prompt, then delegates raw text
// generation to the configured agent provider.
func (g *TextGeneratorAdapter) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	if g.TextGenerator == nil {
		return nil, errors.New("text generator not configured")
	}
	transcriptText := FormatCondensedTranscript(input)
	prompt := buildSummarizationPrompt(transcriptText)

	result, err := g.TextGenerator.GenerateText(ctx, prompt, g.Model)
	if err != nil {
		return nil, fmt.Errorf("provider text generation failed: %w", err)
	}

	return parseSummaryText(result)
}

