376	// generateSummary produces an LLM-generated summary of the session transcript.
377	// The transcript must be pre-redacted to avoid sending secrets to the LLM.
378	// Returns nil if the scoped transcript is empty or generation fails.
379	func generateSummary(ctx context.Context, redactedTranscript redact.RedactedBytes, filesTouched []string, state *SessionState) *cpkg.Summary {
380		summarizeCtx := logging.WithComponent(ctx, "summarize")
381		transcriptBytes := redactedTranscript.Bytes()
382	
383		var scopedTranscript []byte
384		switch state.AgentType {
385		case agent.AgentTypeGemini:
386			scoped, sliceErr := geminicli.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
387			if sliceErr != nil {
388				logging.Warn(summarizeCtx, "failed to scope Gemini transcript for summary",
389					slog.String("session_id", state.SessionID),
390					slog.String("error", sliceErr.Error()))
391			}
392			scopedTranscript = scoped
393		case agent.AgentTypeOpenCode:
394			scoped, sliceErr := opencode.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
395			if sliceErr != nil {
396				logging.Warn(summarizeCtx, "failed to scope OpenCode transcript for summary",
397					slog.String("session_id", state.SessionID),
398					slog.String("error", sliceErr.Error()))
399			}
400			scopedTranscript = scoped
401		case agent.AgentTypeCodex, agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeFactoryAIDroid, agent.AgentTypeUnknown:
402			scopedTranscript = transcript.SliceFromLine(transcriptBytes, state.CheckpointTranscriptStart)
403		}
404	
405		if len(scopedTranscript) == 0 {
406			return nil
407		}
408	
409		generator := buildSummaryGenerator(summarizeCtx)
410		// scopedTranscript is sliced from redactedTranscript, which was redacted earlier in CondenseSession.
411		summary, err := summarize.GenerateFromTranscript(summarizeCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, state.AgentType, generator)
412		if err != nil {
413			logging.Warn(summarizeCtx, "summary generation failed",
414				slog.String("session_id", state.SessionID),
415				slog.String("error", err.Error()))
416			return nil
417		}
418		logging.Info(summarizeCtx, "summary generated",
419			slog.String("session_id", state.SessionID))
420		return summary
421	}
